import { createSelector } from '@base-ui/utils/store';
export const eventCalendarViewSelectors = {
  view: createSelector(state => state.view),
  views: createSelector(state => state.views),
  hasDayView: createSelector(state => state.views.includes('day')),
  /**
   * The user configuration for a time-grid based view (`day` or `week`), or `null` when none is set.
   */
  timeGridConfig: createSelector((state, view) => state.viewConfig?.[view] ?? null)
};